"""
ScholaCore v2 rebuild -- Phase 1 (Firebase schema/rules/.env) + Phase 2
(Student/Teacher auth, Teacher Vetting, Teacher Portal, Admin Dashboard,
Privacy Policy, Terms of Service) deployer.

Run this on your Windows machine with the target repo already cloned.
It writes every file below to disk (base64-embedded, so content is exact,
byte-for-byte, no retyping), then runs git add / commit / push origin main.

Usage:
    python deploy_scholacore_v2.py [path_to_repo]

If no path is given, defaults to the DEFAULT_REPO constant below.
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    '.env.example': '',
    'firebase/firestore.rules': '',
    'firebase/schema.md': '',
    'firebase/storage.rules': '',
    'public/admin-dashboard.html': '',
    'public/css/style.css': '',
    'public/js/firebase-config.js': '',
    'public/privacy-policy.html': '',
    'public/student-signup.html': '',
    'public/teacher-portal.html': '',
    'public/teacher-vetting.html': '',
    'public/terms-of-service.html': '',
}

def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        print("Pass the correct path as an argument, e.g.:")
        print(r"    python deploy_scholacore_v2.py C:\path\to\scholacore")
        sys.exit(1)

    written = []
    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        data = base64.b64decode(b64_content)
        with open(dest, "wb") as f:
            f.write(data)
        written.append(rel_path)
        print(f"wrote: {rel_path}")

    print(f"\n{len(written)} files written to {repo_root}")

    def run(cmd):
        print(">", " ".join(cmd))
        result = subprocess.run(cmd, cwd=repo_root, capture_output=True, text=True)
        print(result.stdout)
        if result.returncode != 0:
            print(result.stderr)
        return result.returncode == 0

    if not run(["git", "add"] + written):
        sys.exit(1)
    commit_msg = "ScholaCore v2: Phase 1 (Firebase schema/rules/.env) + Phase 2 (auth, vetting, portal, admin, compliance pages)"
    if not run(["git", "commit", "-m", commit_msg]):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"])

if __name__ == "__main__":
    main()
